/** Island art URLs (generated by scripts/gen_islands.py; served from our own origin, cached with the app's assets). */
const urls = import.meta.glob("./art/*.svg", { eager: true, query: "?url", import: "default" }) as Record<string, string>;

export const artUrl = (artId: string): string => urls[`./art/${artId}.svg`] ?? urls["./art/generic.svg"]!;
export const homeUrl: string = urls["./art/home.svg"]!;
export const fogUrl: string = urls["./art/fog.svg"]!;
